<!DOCTYPE html><html lang="th"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Admin Management</title><link rel="stylesheet" href="../../css/adminlte.min.css"><link rel="stylesheet" href="https://use.fontawesome.com/releases/v5.15.4/css/all.css"><link rel="stylesheet" href="https://cdn.datatables.net/1.13.8/css/dataTables.bootstrap4.min.css"></head><body class="hold-transition sidebar-mini"><div class="wrapper"><?php include_once('../includes/sidebar.php'); ?><div class="content-wrapper"><section class="content-header"><div class="container-fluid"><div class="row mb-2"><div class="col-sm-6"><h1>Admin Management</h1></div></div></div></section><section class="content"><div class="container-fluid"><div class="card"><div class="card-header"><h3 class="card-title">Admin List</h3><a href="form-create.php" class="btn btn-primary float-right"><i class="fas fa-plus"></i> Add Admin</a></div><div class="card-body"><table id="dataTable" class="table table-bordered table-striped"><thead><tr><th>ID</th><th>Username</th><th>FirstName</th><th>LastName</th><th>Permission</th><th>Last Login</th><th>Edit</th><th>Delete</th></tr></thead><tbody><?php while($r=$result->fetch_assoc()): ?><tr><td><?= (int)$r['id'] ?></td><td><?= htmlspecialchars($r['username']) ?></td><td><?= htmlspecialchars($r['first_name']) ?></td><td><?= htmlspecialchars($r['last_name']) ?></td><td><span class="badge badge-<?= $r['status']==='superadmin'?'warning':'primary' ?>"><?= htmlspecialchars($r['status']) ?></span></td><td><?= htmlspecialchars($r['last_login']) ?></td><td><a href="form-edit.php?id=<?= (int)$r['id'] ?>" class="btn btn-sm btn-warning text-white"><i class="fas fa-edit"></i> แก้ไข</a></td><td><?php if((int)$r['id']!==1 && (int)$r['id']!==(int)$_SESSION['authen_id']): ?><button class="btn btn-sm btn-danger" onclick="deleteItem(<?= (int)$r['id'] ?>)"><i class="fas fa-trash"></i> Delete</button><?php else: ?><span class="text-muted">Protected</span><?php endif; ?></td></tr><?php endwhile; ?></tbody></table></div></div></div></section></div><?php include_once('../includes/footer.php'); ?></div><script src="https://code.jquery.com/jquery-3.7.1.min.js"></script><script src="https://cdn.jsdelivr.net/npm/bootstrap@4.6.2/dist/js/bootstrap.bundle.min.js"></script><script src="../../adminlte.min.js"></script><script src="https://cdn.datatables.net/1.13.8/js/jquery.dataTables.min.js"></script><script src="https://cdn.datatables.net/1.13.8/js/dataTables.bootstrap4.min.js"></script><script>$(function(){$('#dataTable').DataTable({language:{search:'ค้นหา:',lengthMenu:'แสดง _MENU_ รายการ',info:'แสดง _START_ ถึง _END_ จาก _TOTAL_ รายการ',paginate:{previous:'ก่อนหน้า',next:'ถัดไป'},zeroRecords:'ไม่พบข้อมูล'}})});function deleteItem(id){if(confirm('ยืนยันการลบผู้ใช้งานนี้หรือไม่?')) location.href='delete.php?id='+id;}</script></body></html>
